static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    ConvDepthwise2dSquareInputSquareKernelCustomTilingData tiling;

    const gert::Shape* x_shape = context->GetInputShape(0);
    const gert::Shape* w_shape = context->GetInputShape(1);

    // Expect NCHW for x and [C,1,K,K] for w
    uint32_t N = static_cast<uint32_t>(x_shape->GetOriginShape().GetDim(0));
    uint32_t C = static_cast<uint32_t>(x_shape->GetOriginShape().GetDim(1));
    uint32_t H = static_cast<uint32_t>(x_shape->GetOriginShape().GetDim(2));
    uint32_t W = static_cast<uint32_t>(x_shape->GetOriginShape().GetDim(3));
    uint32_t K = static_cast<uint32_t>(w_shape->GetOriginShape().GetDim(2));

    // Assume stride=1, padding=0 (square kernel and input)
    uint32_t outH = H >= K ? (H - K + 1) : 0;
    uint32_t outW = W >= K ? (W - K + 1) : 0;

    // Simple tiling on output H/W
    const uint32_t TILE_H = 32;
    const uint32_t TILE_W = 32;

    // One block per (n,c), cap blockdim
    uint32_t blockDim = N * C;
    if (blockDim == 0) blockDim = 1;
    if (blockDim > 128) blockDim = 128;
    context->SetBlockDim(blockDim);

    tiling.set_n(N);
    tiling.set_c(C);
    tiling.set_h(H);
    tiling.set_w(W);
    tiling.set_k(K);
    tiling.set_outH(outH);
    tiling.set_outW(outW);
    tiling.set_tileH(TILE_H);
    tiling.set_tileW(TILE_W);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *workspace = context->GetWorkspaceSizes(1);
    workspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
}

